/// Every table this file carries, keyed the way `testdata/vectors/errno.json`
/// names its cases, for the vector test.
#[cfg(test)]
pub(super) fn all() -> Vec<(&'static str, Vec<&'static str>)> {
    vec![
        ("linux/amd64", [LINUX.as_slice()].concat()),
        ("linux/386", [LINUX.as_slice()].concat()),
        (
            "linux/arm64",
            [LINUX.as_slice(), LINUX_TAIL_ARM64.as_slice()].concat(),
        ),
        (
            "linux/arm",
            [LINUX.as_slice(), LINUX_TAIL_ARM.as_slice()].concat(),
        ),
        ("darwin/amd64", [DARWIN.as_slice()].concat()),
        (
            "darwin/arm64",
            [DARWIN.as_slice(), DARWIN_TAIL_ARM64.as_slice()].concat(),
        ),
        ("freebsd/amd64", [FREEBSD.as_slice()].concat()),
    ]
}
